"""Build an offline, readable application fieldbook from job-pitch.md."""
from pathlib import Path
import html
import json
import re
from markdown_it import MarkdownIt

ROOT = Path(__file__).resolve().parent
source = (ROOT/'job-pitch.md').read_text()
md = MarkdownIt('commonmark', {'html': False}).enable('table')
parts = re.split(r'^## (.+)\n', source, flags=re.M)
sections = dict(zip(parts[1::2], parts[2::2]))


def render(text):
    value = md.render(text.strip())
    value = re.sub(r'<a href="(https?://[^"]+)"',r'<a target="_blank" rel="noopener noreferrer" href="\1"',value)
    return re.sub(r'(<table>.*?</table>)',r'<div class="table-scroll">\1</div>',value,flags=re.S)


def get(prefix):
    return next(value for key,value in sections.items() if key.startswith(prefix))


def section(identity, title, description, body):
    return f'<section class="chapter" id="{identity}"><div class="chapter-heading"><h2>{title}</h2><p>{description}</p></div><div class="prose">{body}</div></section>'


pitch = get('A 30-second')
cv = get('Three CV')
cv_bullets, cv_notes = cv.split('\n\nThese describe',1)
cv_notes = 'These describe'+cv_notes
linkedin = get('LinkedIn draft')
interview = get('Interview talking')
questions = []
for line in interview.splitlines():
    if not line.startswith('|') or line.startswith('|---'):
        continue
    cells = [cell.strip() for cell in line.strip().strip('|').split('|')]
    if len(cells)==2 and cells[0]!='Question':
        questions.append(f'<details class="question"><summary>{html.escape(cells[0])}<span aria-hidden="true">+</span></summary><div class="prose">{render(cells[1])}</div></details>')

position = section('position','Choose your angle','Lead with the part of the work that matches the role.',render(get('Position the work')))
case = section('case-study','The case study','A reviewer should be able to follow the question, the experiment, and the evidence.',render(get('GitHub case-study')))
interview_html = section('interview','Be ready for the follow-up','The useful details are the ones you can explain at a whiteboard.',''.join(questions))
ledger = section('evidence','Keep the receipts','What you can defend today, and what still needs a result.',render(get('Claim ledger')))
roles = section('roles','Where this work fits','Three official role examples, researched on 18 November 2026.',render(get('What current employers')))

